#!/usr/bin/env python3
# -*- coding: utf-8 -*-
from __future__ import annotations

import py_compile
import shutil
from datetime import datetime
from pathlib import Path

GERADOR = '#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""Gerador final unificado de artigo acadêmico PRISMA/ABNT."""\nfrom __future__ import annotations\n\nimport argparse\nimport contextlib\nimport importlib\nimport io\nimport json\nimport os\nimport re\nimport shutil\nimport subprocess\nimport sys\nimport tempfile\nfrom datetime import datetime\nfrom pathlib import Path\nfrom typing import Iterable\n\nBIBLATEX_ABNT_OPTIONS = (\n    "backend=biber,"\n    "style=abnt,"\n    "language=brazil,"\n    "sorting=nyt,"\n    "giveninits=true,"\n    "uniquename=false,"\n    "uniquelist=false"\n)\n\nBAD_PDF_PATTERNS = [\n    r"LATEX",\n    r"LaTeX",\n    r"\\[[0-9]+(?:,\\s*[0-9]+)*\\]",\n    r"Soares, Ninin e Lima \\(Soares",\n    r"Gabbay et al\\. \\(Gabbay",\n    r"Dijkstra \\(Dijkstra",\n]\n\n\ndef stamp() -> str:\n    return datetime.now().strftime("%Y%m%d_%H%M%S")\n\n\ndef project_root_from_this() -> Path:\n    here = Path(__file__).resolve()\n    for parent in [here.parent, *here.parents]:\n        if (parent / "app_bundle").exists() and (parent / "Pipfile").exists():\n            return parent\n    return Path.cwd().resolve()\n\n\ndef backup(path: Path, tag: str, quiet: bool = False) -> None:\n    if not path.exists():\n        return\n    bak = path.with_name(path.name + f".bak_{tag}_{stamp()}")\n    shutil.copy2(path, bak)\n    if not quiet:\n        print(f"[OK] Backup: {bak}")\n\n\ndef run(cmd: list[str], cwd: Path | None = None, env: dict[str, str] | None = None, quiet: bool = False) -> tuple[int, str]:\n    proc = subprocess.run(\n        cmd,\n        cwd=str(cwd) if cwd else None,\n        env=env,\n        stdout=subprocess.PIPE,\n        stderr=subprocess.STDOUT,\n        check=False,\n    )\n    out = (proc.stdout or b"").decode("utf-8", errors="replace")\n    if not quiet:\n        print("\\n$ " + " ".join(cmd))\n        print(out[-5000:])\n    return int(proc.returncode), out\n\n\ndef call_module_main(module_name: str, argv: list[str], *, quiet: bool = False) -> str:\n    old_argv = sys.argv[:]\n    buf = io.StringIO()\n    try:\n        sys.argv = [module_name.rsplit(".", 1)[-1] + ".py", *argv]\n        cm_out = contextlib.redirect_stdout(buf) if quiet else contextlib.nullcontext()\n        cm_err = contextlib.redirect_stderr(buf) if quiet else contextlib.nullcontext()\n        with cm_out, cm_err:\n            mod = importlib.import_module(module_name)\n            if not hasattr(mod, "main"):\n                raise RuntimeError(f"Módulo sem main(): {module_name}")\n            try:\n                ret = mod.main()\n                code = 0 if ret is None else int(ret)\n            except SystemExit as exc:\n                code = 0 if exc.code is None else int(exc.code)\n        captured = buf.getvalue()\n        if code != 0:\n            raise RuntimeError(f"{module_name} terminou com código {code}.\\n{captured[-5000:]}")\n        return captured\n    finally:\n        sys.argv = old_argv\n\n\ndef set_toml_value_if_present(txt: str, key: str, value: str) -> str:\n    pat = re.compile(rf"(?m)^({re.escape(key)}\\s*=\\s*).*$")\n    if not pat.search(txt):\n        return txt\n    return pat.sub(lambda m: m.group(1) + value, txt)\n\n\ndef ensure_cfg(cfg: Path, template_cfg: Path | None, quiet: bool = False) -> None:\n    if cfg.exists():\n        return\n    if template_cfg is None:\n        raise SystemExit(f"ERRO: TOML não encontrado: {cfg}\\nInforme --template-cfg ou crie o TOML antes.")\n    if not template_cfg.exists():\n        raise SystemExit(f"ERRO: template TOML não encontrado: {template_cfg}")\n    cfg.parent.mkdir(parents=True, exist_ok=True)\n    shutil.copy2(template_cfg, cfg)\n    if not quiet:\n        print(f"[OK] TOML criado: {cfg}")\n\n\ndef prepare_cfg(cfg: Path, target_n: int, min_palavras: int, quiet: bool = False) -> None:\n    backup(cfg, "artigo_final_unificado", quiet=quiet)\n    txt = cfg.read_text(encoding="utf-8", errors="ignore")\n    replacements = {\n        "target_n": str(target_n),\n        "target_n_fulltext": str(target_n),\n        "min_palavras": str(min_palavras),\n        "min_palavras_total": str(min_palavras),\n        "usar_biber": "true",\n        "usar_biblatex": "true",\n        "estilo_bibliografia": \'"abnt"\',\n    }\n    for key, value in replacements.items():\n        txt = set_toml_value_if_present(txt, key, value)\n    cfg.write_text(txt, encoding="utf-8")\n\n\ndef parse_bib_keys(bib: Path) -> list[str]:\n    if not bib.exists():\n        return []\n    txt = bib.read_text(encoding="utf-8", errors="ignore")\n    return re.findall(r"@\\w+\\s*\\{\\s*([^,\\s]+)", txt)\n\n\ndef sanitize_bib(bib: Path, quiet: bool = False) -> None:\n    if not bib.exists():\n        raise SystemExit(f"ERRO: BIB não encontrado: {bib}")\n    backup(bib, "bib_saneado", quiet=quiet)\n    txt = bib.read_text(encoding="utf-8", errors="ignore")\n    field_names = ["author", "editor", "title", "journaltitle", "journal", "publisher", "institution", "organization"]\n    for field in field_names:\n        pattern = re.compile(rf"(?im)^(\\s*{field}\\s*=\\s*[\\{{\\"])(.*?)([\\}}\\"],?\\s*)$")\n        def repl(m: re.Match[str]) -> str:\n            start, value, end = m.groups()\n            if field in {"author", "editor"}:\n                value = value.replace(";", " and ")\n            value = value.replace(" & ", r" \\& ")\n            return start + value + end\n        txt = pattern.sub(repl, txt)\n    bib.write_text(txt, encoding="utf-8")\n\n\ndef convert_literal_citations(txt: str, keys: list[str]) -> str:\n    if not keys:\n        return txt\n    keyset = set(keys)\n    def repl_key(m: re.Match[str]) -> str:\n        key = m.group(1)\n        return rf"\\parencite{{{key}}}" if key in keyset else m.group(0)\n    txt = re.sub(r"\\[([A-Za-z][A-Za-z0-9:_\\-.]{4,})\\]", repl_key, txt)\n    def repl_num(m: re.Match[str]) -> str:\n        raw = m.group(1)\n        nums: list[int] = []\n        for piece in raw.split(","):\n            piece = piece.strip()\n            if not piece.isdigit():\n                return m.group(0)\n            nums.append(int(piece))\n        if nums and all(1 <= n <= len(keys) for n in nums):\n            return rf"\\parencite{{{\',\'.join(keys[n - 1] for n in nums)}}}"\n        return m.group(0)\n    return re.sub(r"(?<![A-Za-z0-9])\\[([0-9]+(?:\\s*,\\s*[0-9]+)*)\\](?![A-Za-z0-9])", repl_num, txt)\n\n\ndef generic_text_fixes(txt: str) -> str:\n    novo = "evitando tabela extensa de difícil leitura e preservando a rastreabilidade das citações"\n    txt = re.sub(\n        r"evitando\\s+tabela\\s+larga\\s+no\\s*(?:LATEX|LaTeX|\\\\LaTeX(?:\\{\\})?)\\s*e\\s+preservando\\s+a\\s+rastreabilidade\\s+das\\s+citações",\n        novo,\n        txt,\n        flags=re.I,\n    )\n    for old in [\n        "evitando tabela larga no LATEX e preservando a rastreabilidade das citações",\n        "evitando tabela larga no LaTeX e preservando a rastreabilidade das citações",\n        r"evitando tabela larga no \\LaTeX{} e preservando a rastreabilidade das citações",\n        r"evitando tabela larga no \\LaTeX e preservando a rastreabilidade das citações",\n    ]:\n        txt = txt.replace(old, novo)\n    txt = txt.replace(r"$\\backslash$%", r"\\%")\n    txt = txt.replace(r"\\textbackslash{}", "")\n    return txt\n\n\ndef remove_org_bib_headers(txt: str) -> str:\n    patterns = [\n        r"(?m)^#\\+LATEX_HEADER:\\s*\\\\usepackage(?:\\[[^\\]]*\\])?\\{biblatex\\}\\s*$",\n        r"(?m)^#\\+LATEX_HEADER:\\s*\\\\addbibresource\\{[^}]+\\}\\s*$",\n        r"(?m)^#\\+LATEX_HEADER:\\s*\\\\usepackage(?:\\[[^\\]]*\\])?\\{abntex2cite\\}\\s*$",\n        r"(?m)^#\\+LATEX_HEADER:\\s*\\\\bibliographystyle\\{[^}]+\\}\\s*$",\n        r"(?m)^#\\+LATEX_HEADER:\\s*\\\\bibliography\\{[^}]+\\}\\s*$",\n    ]\n    for pat in patterns:\n        txt = re.sub(pat, "", txt)\n    return txt\n\n\ndef insert_org_bib_headers(txt: str, bib_name: str) -> str:\n    lines = txt.splitlines()\n    insert_at = 0\n    for i, line in enumerate(lines):\n        if line.startswith("#+"):\n            insert_at = i + 1\n    headers = [\n        rf"#+LATEX_HEADER: \\usepackage[{BIBLATEX_ABNT_OPTIONS}]{{biblatex}}",\n        rf"#+LATEX_HEADER: \\addbibresource{{{bib_name}}}",\n    ]\n    for h in reversed(headers):\n        lines.insert(insert_at, h)\n    return "\\n".join(lines).rstrip() + "\\n"\n\n\ndef ensure_org_references(txt: str) -> str:\n    txt = re.sub(r"(?m)^\\\\bibliographystyle\\{[^}]+\\}\\s*$", "", txt)\n    txt = re.sub(r"(?m)^\\\\bibliography\\{[^}]+\\}\\s*$", "", txt)\n    if r"\\printbibliography" not in txt:\n        txt = txt.rstrip() + "\\n\\n* Referências\\n\\\\nocite{*}\\n\\\\printbibliography[heading=none]\\n"\n    return txt\n\n\ndef patch_org(org: Path, bib_name: str, keys: list[str], quiet: bool = False) -> None:\n    if not org.exists():\n        raise SystemExit(f"ERRO: ORG não encontrado: {org}")\n    backup(org, "org_abnt", quiet=quiet)\n    txt = org.read_text(encoding="utf-8", errors="ignore")\n    txt = remove_org_bib_headers(txt)\n    txt = insert_org_bib_headers(txt, bib_name)\n    txt = convert_literal_citations(txt, keys)\n    txt = txt.replace(r"\\cite{", r"\\parencite{")\n    txt = generic_text_fixes(txt)\n    txt = ensure_org_references(txt)\n    org.write_text(txt, encoding="utf-8")\n\n\ndef make_export_el(project_root: Path, org: Path) -> str:\n    root_s = json.dumps(str(project_root))\n    org_s = json.dumps(str(org))\n    return f\'\'\'(setq debug-on-error t)\n(require \'org)\n(require \'ox-latex)\n(let* ((project-root {root_s})\n       (org-file {org_s})\n       (misc-dir (expand-file-name "app_bundle/misc" project-root))\n       (academic-writing (expand-file-name "app_bundle/misc/academic-writing.el" project-root)))\n  (add-to-list \'load-path misc-dir)\n  (when (file-exists-p academic-writing)\n    (load-file academic-writing))\n  (when (fboundp \'gm/academic-setup)\n    (gm/academic-setup))\n  (unless (assoc "fgv-paper" org-latex-classes)\n    (add-to-list\n     \'org-latex-classes\n     \'("fgv-paper"\n       "\\\\documentclass[12pt,a4paper]{{article}}\n[NO-DEFAULT-PACKAGES]\n[PACKAGES]\n\\\\usepackage{{fgv-paper}}\n[EXTRA]"\n       ("\\\\section{{%s}}" . "\\\\section*{{%s}}")\n       ("\\\\subsection{{%s}}" . "\\\\subsection*{{%s}}")\n       ("\\\\subsubsection{{%s}}" . "\\\\subsubsection*{{%s}}")\n       ("\\\\paragraph{{%s}}" . "\\\\paragraph*{{%s}}"))))\n  (find-file org-file)\n  (org-latex-export-to-latex))\n\'\'\'\n\n\ndef export_org_to_tex(org: Path, out: Path, quiet: bool = False) -> None:\n    if shutil.which("emacs") is None:\n        raise SystemExit("ERRO: emacs não encontrado no PATH.")\n    project_root = project_root_from_this()\n    with tempfile.NamedTemporaryFile("w", suffix=".el", encoding="utf-8", delete=False) as fh:\n        fh.write(make_export_el(project_root, org))\n        el_path = Path(fh.name)\n    try:\n        code, output = run(["emacs", "--batch", "-l", str(el_path)], cwd=out, quiet=quiet)\n    finally:\n        try:\n            el_path.unlink()\n        except FileNotFoundError:\n            pass\n    if code != 0:\n        raise SystemExit(f"ERRO: falha no export Org -> TeX.\\n{output[-5000:]}")\n\n\ndef remove_tex_bib_config(tex: str) -> str:\n    for pat in [\n        r"(?m)^\\\\PassOptionsToPackage\\{[^}]*\\}\\{biblatex\\}\\s*$",\n        r"(?m)^\\\\usepackage(?:\\[[^\\]]*\\])?\\{biblatex\\}\\s*$",\n        r"(?m)^\\\\addbibresource\\{[^}]+\\}\\s*$",\n        r"(?m)^\\\\usepackage(?:\\[[^\\]]*\\])?\\{abntex2cite\\}\\s*$",\n        r"(?m)^\\\\bibliographystyle\\{[^}]+\\}\\s*$",\n        r"(?m)^\\\\bibliography\\{[^}]+\\}\\s*$",\n    ]:\n        tex = re.sub(pat, "", tex)\n    return tex\n\n\ndef insert_tex_bib_config(tex: str, bib_name: str) -> str:\n    if r"\\begin{document}" not in tex:\n        raise SystemExit("ERRO: \\\\begin{document} não encontrado no TEX.")\n    insert = rf"\\usepackage[{BIBLATEX_ABNT_OPTIONS}]{{biblatex}}" + "\\n" + rf"\\addbibresource{{{bib_name}}}" + "\\n"\n    return tex.replace(r"\\begin{document}", insert + r"\\begin{document}", 1)\n\n\ndef ensure_tex_references(tex: str) -> str:\n    tex = re.sub(r"(?m)^\\\\bibliographystyle\\{[^}]+\\}\\s*$", "", tex)\n    tex = re.sub(r"(?m)^\\\\bibliography\\{[^}]+\\}\\s*$", "", tex)\n    if r"\\printbibliography" not in tex:\n        tex = tex.replace(r"\\end{document}", r"\\section{Referências}" + "\\n" + r"\\nocite{*}" + "\\n" + r"\\printbibliography[heading=none]" + "\\n" + r"\\end{document}", 1)\n    return tex\n\n\ndef patch_tex(tex_path: Path, bib_name: str, keys: list[str], quiet: bool = False) -> None:\n    if not tex_path.exists():\n        raise SystemExit(f"ERRO: TEX não encontrado: {tex_path}")\n    backup(tex_path, "tex_abnt", quiet=quiet)\n    tex = tex_path.read_text(encoding="utf-8", errors="ignore")\n    tex = remove_tex_bib_config(tex)\n    tex = insert_tex_bib_config(tex, bib_name)\n    tex = convert_literal_citations(tex, keys)\n    tex = tex.replace(r"\\cite{", r"\\parencite{")\n    tex = generic_text_fixes(tex)\n    tex = ensure_tex_references(tex)\n    tex_path.write_text(tex, encoding="utf-8")\n\n\ndef compile_pdf(out: Path, prefix: str, quiet: bool = False) -> Path:\n    for tool in ["pdflatex", "biber"]:\n        if shutil.which(tool) is None:\n            raise SystemExit(f"ERRO: {tool} não encontrado no PATH.")\n    tex = out / f"{prefix}.tex"\n    pdf = out / f"{prefix}.pdf"\n    if not tex.exists():\n        raise SystemExit(f"ERRO: TEX não encontrado: {tex}")\n    for ext in ["pdf", "aux", "bbl", "bcf", "blg", "log", "out", "run.xml", "toc"]:\n        p = out / f"{prefix}.{ext}"\n        if p.exists():\n            p.unlink()\n    project_root = project_root_from_this()\n    texinputs_parts = [\n        ".",\n        str(out),\n        str(project_root),\n        str(project_root / "app_bundle" / "misc"),\n        str(project_root / "app_bundle" / "misc" / "fgv"),\n        str(project_root / "app_bundle" / "institutions" / "fgv" / "latex"),\n    ]\n    env = os.environ.copy()\n    env["TEXINPUTS"] = ":".join(texinputs_parts) + ":" + env.get("TEXINPUTS", "")\n    env["BIBINPUTS"] = f".:{out}:" + env.get("BIBINPUTS", "")\n    for cmd in [\n        ["pdflatex", "-file-line-error", "-interaction=nonstopmode", f"{prefix}.tex"],\n        ["biber", prefix],\n        ["pdflatex", "-file-line-error", "-interaction=nonstopmode", f"{prefix}.tex"],\n        ["pdflatex", "-file-line-error", "-interaction=nonstopmode", f"{prefix}.tex"],\n    ]:\n        code, output = run(cmd, cwd=out, env=env, quiet=quiet)\n        if code != 0:\n            raise SystemExit(f"ERRO: falha em {\' \'.join(cmd)}\\n{output[-5000:]}")\n    if not pdf.exists():\n        raise SystemExit(f"ERRO: PDF não foi gerado: {pdf}")\n    return pdf\n\n\ndef validate_pdf(pdf: Path, quiet: bool = False) -> None:\n    if shutil.which("pdftotext") is None:\n        if not quiet:\n            print("[AVISO] pdftotext ausente; validação textual pulada.")\n        return\n    code, txt = run(["pdftotext", str(pdf), "-"], quiet=True)\n    if code != 0:\n        raise SystemExit("ERRO: pdftotext falhou.")\n    hits: list[str] = []\n    for i, line in enumerate(txt.splitlines(), start=1):\n        for pat in BAD_PDF_PATTERNS:\n            if re.search(pat, line):\n                hits.append(f"{i}:{line}")\n                break\n    if hits:\n        raise SystemExit("ERRO: validação encontrou problemas no PDF final:\\n" + "\\n".join(hits[:40]))\n    if not quiet:\n        print("[OK] PDF validado.")\n\n\ndef prepare_fulltext(art: Path, cfg: Path, target_n: int, min_palavras: int, chars_por_pdf: int, quiet: bool) -> None:\n    call_module_main(\n        "app_bundle.scripts.pipeline.preparar_artigo_longo_fulltext",\n        ["--art-dir", str(art), "--cfg-art", str(cfg), "--target-n", str(target_n), "--min-palavras", str(min_palavras), "--chars-por-pdf", str(chars_por_pdf)],\n        quiet=quiet,\n    )\n\n\ndef generate_article(art: Path, cfg: Path, quiet: bool) -> None:\n    call_module_main(\n        "app_bundle.scripts.pipeline.gerar_artigo_longo_fulltext_secional",\n        ["--art-dir", str(art), "--cfg-art", str(cfg)],\n        quiet=quiet,\n    )\n\n\ndef finalize_existing(art: Path, cfg: Path, prefix: str, quiet: bool) -> Path:\n    out = art / "output"\n    org = out / f"{prefix}.org"\n    tex = out / f"{prefix}.tex"\n    bib = out / f"{prefix}.bib"\n    if not out.exists():\n        raise SystemExit(f"ERRO: output não encontrado: {out}")\n    if not org.exists():\n        raise SystemExit(f"ERRO: ORG não encontrado: {org}")\n    if not bib.exists():\n        raise SystemExit(f"ERRO: BIB não encontrado: {bib}")\n    sanitize_bib(bib, quiet=quiet)\n    keys = parse_bib_keys(bib)\n    patch_org(org, bib.name, keys, quiet=quiet)\n    export_org_to_tex(org, out, quiet=quiet)\n    patch_tex(tex, bib.name, keys, quiet=quiet)\n    pdf = compile_pdf(out, prefix, quiet=quiet)\n    validate_pdf(pdf, quiet=quiet)\n    return pdf\n\n\ndef main(argv: Iterable[str] | None = None) -> int:\n    parser = argparse.ArgumentParser(description="Gera artigo final PRISMA/ABNT em PDF por fluxo unificado.")\n    parser.add_argument("--art-dir", required=True, help="Diretório do artigo.")\n    parser.add_argument("--cfg-art", required=True, help="TOML do artigo final.")\n    parser.add_argument("--template-cfg", default="", help="Template TOML se --cfg-art não existir.")\n    parser.add_argument("--prefix", default="", help="Prefixo dos arquivos finais. Padrão: stem do TOML.")\n    parser.add_argument("--target-n", type=int, default=20)\n    parser.add_argument("--min-palavras", type=int, default=8500)\n    parser.add_argument("--chars-por-pdf", type=int, default=18000)\n    parser.add_argument("--skip-prepare", action="store_true", help="Não prepara full text/corpus.")\n    parser.add_argument("--skip-generate", action="store_true", help="Não gera texto novo; só finaliza ORG/TEX/BIB existentes.")\n    parser.add_argument("--quiet", action="store_true")\n    args = parser.parse_args(list(argv) if argv is not None else None)\n\n    root = project_root_from_this()\n    if str(root) not in sys.path:\n        sys.path.insert(0, str(root))\n\n    art = Path(args.art_dir).expanduser().resolve()\n    cfg = Path(args.cfg_art).expanduser().resolve()\n    template = Path(args.template_cfg).expanduser().resolve() if args.template_cfg else None\n    prefix = str(args.prefix or cfg.stem).strip()\n\n    if not art.exists():\n        raise SystemExit(f"ERRO: diretório do artigo não encontrado: {art}")\n    ensure_cfg(cfg, template, quiet=args.quiet)\n\n    if not (args.skip_prepare and args.skip_generate):\n        prepare_cfg(cfg, args.target_n, args.min_palavras, quiet=args.quiet)\n    elif not args.quiet:\n        print("[OK] Modo recompilação: TOML preservado.")\n\n    if not args.skip_prepare:\n        prepare_fulltext(art, cfg, args.target_n, args.min_palavras, args.chars_por_pdf, args.quiet)\n    if not args.skip_generate:\n        generate_article(art, cfg, args.quiet)\n\n    pdf = finalize_existing(art, cfg, prefix, args.quiet)\n    print(f"[OK] PDF final: {pdf}")\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'


def stamp() -> str:
    return datetime.now().strftime("%Y%m%d_%H%M%S")


def main() -> int:
    root = Path.cwd().resolve()
    if not (root / "app_bundle").exists():
        raise SystemExit("ERRO: execute este aplicador na raiz do projeto, onde existe app_bundle/.")

    targets = [
        root / "gerar_artigo_final_unificado.py",
        root / "app_bundle" / "scripts" / "pipeline" / "gerar_artigo_final_unificado.py",
    ]

    for p in targets:
        p.parent.mkdir(parents=True, exist_ok=True)
        if p.exists():
            bak = p.with_name(p.name + ".bak_v5_export_fgv_" + stamp())
            shutil.copy2(p, bak)
            print(f"[OK] Backup: {bak}")
        p.write_text(GERADOR, encoding="utf-8")
        print(f"[OK] Escrito: {p}")
        py_compile.compile(str(p), doraise=True)
        print(f"[OK] py_compile: {p}")

    print("\n[OK] Gerador unificado reparado na versão v5.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
